package com.gymmind.membership.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.membership.domain.model.MembershipPackage; import com.gymmind.membership.domain.repository.MembershipPackageRepository; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map; @Service public class DefaultMembershipPackageService implements MembershipPackageService{private final MembershipPackageRepository packages;private final AuditRecorder audit;public DefaultMembershipPackageService(MembershipPackageRepository p,AuditRecorder a){packages=p;audit=a;} @Override @Transactional public MembershipPackageView create(CurrentActor a,CreateMembershipPackageCommand c){require(a,"membership:write");if(c==null||c.tenantId()!=null&&!a.tenantId().equals(c.tenantId()))throw new BusinessException(ErrorCode.FORBIDDEN);MembershipPackage p=packages.save(MembershipPackage.create(a.tenantId(),c.name(),c.entitlementType(),c.entitlementCount(),c.validDays(),c.price(),c.currency()));audit.record(new AuditEvent("MEMBERSHIP_PACKAGE_CREATED","MEMBERSHIP_PACKAGE",p.getId(),AuditResult.SUCCESS,"membership-service",Map.of()));return MembershipPackageView.from(p);} @Override @Transactional(readOnly=true) public MembershipPackageView find(CurrentActor a,Long id){require(a,"membership:read");MembershipPackage p=packages.findByTenantIdAndId(a.tenantId(),id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));return MembershipPackageView.from(p);}private static void require(CurrentActor a,String p){if(a==null||a.tenantId()==null||!a.roles().contains(RoleCode.GYM_ADMIN)||!a.hasPermission(p))throw new BusinessException(ErrorCode.FORBIDDEN);}}
